import type { CSSProperties, Ref } from 'react'

// Sizes generated by `npm run images` (scripts/images.mjs). ratio = height / width.
const IMAGES = {
  'boats': { widths: [640, 1280, 1920], ratio: 0.75 },
  'keke-street': { widths: [640, 1280, 1920], ratio: 0.9865 },
  'kura-bike': { widths: [640], ratio: 0.6257 },
  'kura-boat': { widths: [638], ratio: 0.7524 },
  'kura-keke-fleet': { widths: [640], ratio: 0.642 },
  'kura-keke-hub': { widths: [638], ratio: 0.7524 },
  'kura-rider': { widths: [640], ratio: 0.6667 },
  'lagoon-boats': { widths: [640, 1280, 1920], ratio: 0.75 },
  'lagos-aerial': { widths: [640, 1280, 1920], ratio: 0.5625 },
  'lagos-traffic': { widths: [640, 1280, 1920], ratio: 0.6665 },
  'okada-riders': { widths: [640, 1280, 1920], ratio: 1.3335 },
  'rider-motion': { widths: [640, 1280, 1920], ratio: 1.5015 },
} as const

export type ImageName = keyof typeof IMAGES

const srcset = (name: ImageName, ext: string) =>
  IMAGES[name].widths.map((w) => `/images/${name}-${w}.${ext} ${w}w`).join(', ')

/** <picture> with AVIF/WebP/JPEG at several widths; never shifts layout. */
export function Photo({
  name,
  alt,
  sizes = '100vw',
  className = '',
  imgClassName = '',
  priority = false,
  imgRef,
  style,
}: {
  name: ImageName
  alt: string
  sizes?: string
  className?: string
  imgClassName?: string
  priority?: boolean
  imgRef?: Ref<HTMLImageElement>
  style?: CSSProperties
}) {
  const img = IMAGES[name]
  const widths: readonly number[] = img.widths
  const w = widths[Math.min(1, widths.length - 1)]!
  return (
    <picture className={className}>
      <source type="image/avif" srcSet={srcset(name, 'avif')} sizes={sizes} />
      <source type="image/webp" srcSet={srcset(name, 'webp')} sizes={sizes} />
      <img
        ref={imgRef}
        src={`/images/${name}-${w}.jpg`}
        srcSet={srcset(name, 'jpg')}
        sizes={sizes}
        alt={alt}
        width={w}
        height={Math.round(w * img.ratio)}
        loading={priority ? 'eager' : 'lazy'}
        decoding="async"
        fetchPriority={priority ? 'high' : 'auto'}
        className={imgClassName}
        style={style}
      />
    </picture>
  )
}
